  if ((carry & ~7u) != 0) {
    return false;
  }
  unsigned needed = 0;
  while (needed < 3 && (carry & (1u << needed)) != 0) {
    ++needed;
  }
  if (carry != ((1u << needed) - 1u) || needed > length) {
