    return false;
  }
  for (unsigned i = 0; i < needed; ++i) {
    if ((bytes[i] & 0xC0) != 0x80) {
      return false;
    }
  }
  return validate_utf8_scalar(bytes + needed, length - needed);
}

static bool validate_utf8_simd(const unsigned char *bytes, size_t length) {
